parameters.text:
=Analizá el siguiente documento y generá un resumen estructurado.

Documento:
{{ $json.body.documento }}

Respondé SOLO con un JSON válido con esta estructura:
{
  "resumen": "resumen en 2-3 oraciones",
  "datos_clave": {
    "personas": ["nombres mencionados"],
    "fechas": ["fechas encontradas"],
    "numeros_documento": ["DNI, expediente, etc"]
  },
  "puntos_principales": ["punto 1", "punto 2", "punto 3"],
  "categoria": "tipo de documento detectado",
  "acciones_pendientes": ["si hay alguna acción requerida"]
}

parameters.jsCode:
const textoLLM = $input.all()[0].json.text;
try {
  const analisis = JSON.parse(textoLLM);
  return [{ json: { exito: true, analisis, documento_original_largo: $('Webhook - Recibe Documento').item.json.body.documento.length + ' caracteres' } }];
} catch (e) {
  return [{ json: { exito: false, error: 'No se pudo parsear la respuesta', respuesta_cruda: textoLLM } }];
}
